export interface GameEntry {
  id: string;
  name: string;
  category: GameCategory;
  energySystem: 'Phosphagen' | 'Glycolytic' | 'Oxidative' | 'Hybrid';
  difficulty: 'Beginner' | 'Intermediate' | 'Advanced' | 'Elite';
  olympicStatus: string;
  keyMovement: string;
  primaryFault: string;
  biomechanicalFoci: string[];
  equipment: string[];
}

export type GameCategory =
  | 'Ball & Invasion Games'
  | 'Racket & Paddle Sports'
  | 'Bat & Striking Games'
  | 'Track & Field Athletics'
  | 'Combat & Martial Arts'
  | 'Strength & Powerlifting'
  | 'Aquatic & Water Sports'
  | 'Cycling & Wheel Sports'
  | 'Winter Sports'
  | 'Gymnastics & Calisthenics'
  | 'Target & Precision Sports'
  | 'Action & Adventure Sports'
  | 'Traditional & Emerging Games';

// Compact generator helper to build full catalog cleanly
function g(
  id: string,
  name: string,
  category: GameCategory,
  energySystem: 'Phosphagen' | 'Glycolytic' | 'Oxidative' | 'Hybrid',
  difficulty: 'Beginner' | 'Intermediate' | 'Advanced' | 'Elite',
  olympicStatus: string,
  keyMovement: string,
  primaryFault: string,
  biomechanicalFoci: string[],
  equipment: string[]
): GameEntry {
  return { id, name, category, energySystem, difficulty, olympicStatus, keyMovement, primaryFault, biomechanicalFoci, equipment };
}

