// Helper to filter and search through the 200+ games
export function searchGames(query: string, category?: GameCategory | 'All'): GameEntry[] {
  return ALL_GAMES_DATABASE.filter((game) => {
    const matchesCategory = !category || category === 'All' || game.category === category;
    const q = query.toLowerCase().trim();
    if (!q) return matchesCategory;
    const matchesQuery =
      game.name.toLowerCase().includes(q) ||
      game.keyMovement.toLowerCase().includes(q) ||
      game.category.toLowerCase().includes(q) ||
      game.biomechanicalFoci.some((f) => f.toLowerCase().includes(q));
    return matchesCategory && matchesQuery;
  });
}
